    Result ISslConnection::DoHandshakeImpl(ipc::IpcRequest&r,ipc::IpcResponse&resp,bool withCert){auto out{withCert?Out(r):std::optional<span<u8>>{}};if(withCert&&!out)return result::InvalidCertificateBufferSize;Result rc{backend.Handshake(enableAlpn)};verifyErrors=backend.VerificationErrors();if(rc)return rc;if(!withCert)return{};if(!(verifyOption&VerifyPeerCa)){resp.Push<u32>(0);resp.Push<u32>(0);return{};}auto chain{backend.PeerCertificateChain()};auto data{Serialize(chain,getServerCertChain)};if(!data)return data.result;if(out->size()<data->size())return result::CertificateBufferTooSmall;std::memcpy(out->data(),data->data(),data->size());resp.Push<u32>(static_cast<u32>(data->size()));resp.Push<u32>(getServerCertChain?static_cast<u32>(chain.size()):1);return{};}
