    Result ISslConnection::Read(type::KSession&,ipc::IpcRequest&r,ipc::IpcResponse&resp){if(socket<0)return result::NoSocket;auto out{Out(r)};if(!out||out->empty())return result::InvalidCertificateBufferSize;size_t count{};while(count<out->size()&&!peekBuffer.empty()){(*out)[count++]=peekBuffer.front();peekBuffer.pop_front();}if(!count){auto read{backend.Read(*out)};if(!read)return read.result;count=*read;}resp.Push<u32>(static_cast<u32>(count));return{};}
