    Result ISslConnection::Pending(type::KSession&,ipc::IpcRequest&,ipc::IpcResponse&resp){if(socket<0)return result::NoSocket;u64 count{peekBuffer.size()+backend.Pending()};resp.Push<i32>(static_cast<i32>(std::min<u64>(count,INT_MAX)));return{};}
    Result ISslConnection::Peek(type::KSession&,ipc::IpcRequest&r,ipc::IpcResponse&resp){if(socket<0)return result::NoSocket;auto out{Out(r)};if(!out||out->empty())return result::InvalidCertificateBufferSize;if(peekBuffer.empty()){std::vector<u8>tmp(out->size());auto read{backend.Read(tmp)};if(!read)return read.result;peekBuffer.insert(peekBuffer.end(),tmp.begin(),tmp.begin()+static_cast<ptrdiff_t>(*read));}size_t count{std::min(out->size(),peekBuffer.size())};std::copy_n(peekBuffer.begin(),count,out->begin());resp.Push<u32>(static_cast<u32>(count));return{};}
    Result ISslConnection::Poll(type::KSession&,ipc::IpcRequest&r,ipc::IpcResponse&resp){auto ev{Arg<u32>(r)},timeout{Arg<u32>(r,4)};if(!ev||!timeout||(*ev&~PollAll))return result::InvalidOption;if(socket<0)return result::NoSocket;u32 out{};if((*ev&PollRead)&&(!peekBuffer.empty()||backend.Pending()))out|=PollRead;if(!out){short host{};if(*ev&PollRead)host|=POLLIN;if(*ev&PollWrite)host|=POLLOUT;if(*ev&PollExcept)host|=POLLPRI;pollfd p{socket,host,0};int rc{::poll(&p,1,static_cast<int>(std::min<u32>(*timeout,INT_MAX)))};if(rc<0)return errno==EINTR?result::WouldBlock:result::IoAborted;if(p.revents&(POLLIN|POLLHUP))out|=PollRead;if(p.revents&POLLOUT)out|=PollWrite;if(p.revents&(POLLPRI|POLLERR|POLLNVAL))out|=PollExcept;}resp.Push<u32>(out);return{};}
    Result ISslConnection::GetVerifyCertError(type::KSession&,ipc::IpcRequest&,ipc::IpcResponse&){if(verifyErrors.empty())return{};Result e{verifyErrors.front()};verifyErrors.erase(verifyErrors.begin());return e;}
    Result ISslConnection::GetNeededServerCertBufferSize(type::KSession&,ipc::IpcRequest&,ipc::IpcResponse&resp){if(!backend.IsHandshaken())return result::NoConnection;auto data{Serialize(backend.PeerCertificateChain(),getServerCertChain)};if(!data)return data.result;resp.Push<u32>(static_cast<u32>(data->size()));return{};}
    Result ISslConnection::SetSessionCacheMode(type::KSession&,ipc::IpcRequest&r,ipc::IpcResponse&){if(socket<0)return result::NoSocket;auto v{Arg<u32>(r)};if(!v)return result::InvalidOption;auto mode{static_cast<SessionCacheMode>(*v)};if(Result rc{backend.SetSessionCacheMode(mode)};rc)return rc;sessionCacheMode=mode;return{};} Result ISslConnection::GetSessionCacheMode(type::KSession&,ipc::IpcRequest&,ipc::IpcResponse&resp){if(socket<0)return result::NoSocket;resp.Push<u32>(static_cast<u32>(sessionCacheMode));return{};}
