    Result ISslConnection::SetOption(type::KSession&,ipc::IpcRequest&r,ipc::IpcResponse&){auto flag{Arg<u8>(r)};auto raw{Arg<u32>(r,4)};if(!flag||!raw||*flag>1)return result::InvalidOption;auto opt{static_cast<OptionType>(*raw)};if(opt==OptionType::DoNotCloseSocket&&socket>=0)return result::AlreadyInUse;if(opt==OptionType::GetServerCertChain&&contextState->interfaceVersion<1)return result::InvalidOption;if(opt==OptionType::SkipDefaultVerify&&contextState->interfaceVersion<2)return result::InvalidOption;if(opt==OptionType::EnableAlpn&&contextState->interfaceVersion<3)return result::InvalidOption;switch(opt){case OptionType::DoNotCloseSocket:doNotCloseSocket=*flag;break;case OptionType::GetServerCertChain:getServerCertChain=*flag;break;case OptionType::SkipDefaultVerify:skipDefaultVerify=*flag;break;case OptionType::EnableAlpn:enableAlpn=*flag;break;default:return result::InvalidOption;}return{};}
    Result ISslConnection::GetOption(type::KSession&,ipc::IpcRequest&r,ipc::IpcResponse&resp){auto raw{Arg<u32>(r)};if(!raw)return result::InvalidOption;auto option{static_cast<OptionType>(*raw)};if((option==OptionType::GetServerCertChain&&contextState->interfaceVersion<1)||(option==OptionType::SkipDefaultVerify&&contextState->interfaceVersion<2)||(option==OptionType::EnableAlpn&&contextState->interfaceVersion<3))return result::InvalidOption;bool v{};switch(option){case OptionType::DoNotCloseSocket:v=doNotCloseSocket;break;case OptionType::GetServerCertChain:v=getServerCertChain;break;case OptionType::SkipDefaultVerify:v=skipDefaultVerify;break;case OptionType::EnableAlpn:v=enableAlpn;break;default:return result::InvalidOption;}resp.Push<u8>(v);return{};}
