    Result ISslConnection::GetCipherInfo(type::KSession&,ipc::IpcRequest&r,ipc::IpcResponse&){auto v{Arg<u32>(r)};auto out{Out(r)};if(!backend.IsHandshaken())return result::NoConnection;if(!v||*v!=1||!out||out->size()!=sizeof(CipherInfo))return result::InvalidOption;CipherInfo info{};auto cipher{backend.CipherName()},protocol{backend.ProtocolVersion()};std::memcpy(info.cipher,cipher.data(),std::min(cipher.size(),sizeof(info.cipher)-1));std::memcpy(info.protocolVersion,protocol.data(),std::min(protocol.size(),sizeof(info.protocolVersion)-1));std::memcpy(out->data(),&info,sizeof(info));return{};}
